//! SDIO / SD-card pad functions of the SWM341 pin matrix.
//!
//! Generated by `scripts/gen_pin_func.py` from the vendor header
//! `SWM341_port.h` -- do not edit by hand.
//!
//! Each `Pin{n}Func` enumerates the SD-card (`SD_*`) functions selectable on pin
//! `{n}` of its bank; the numeric value of every variant is the 4-bit code
//! written into `PORTx.FUNC0/FUNC1`. Unlike the analog peripherals these are
//! not a fixed code -- they differ per pad (CLK `7`, CMD `8`, D0 `8`, D1 `6`,
//! ...), which is why the table is generated rather than transcribed. Code `0`
//! (generic GPIO) is omitted. The variants are the type-checked arguments to
//! [`crate::sdio::Sdio::new`] and friends.


/// Generate the per-pin `Pin{n}Func` enums for one bank module.
///
/// Each entry is `PinType => Enum { Variant = func_code, ... }`; the macro
/// writes the `#[repr(u8)]` enum plus its `PinFunc` / `PinFuncOf` impls.
macro_rules! pad_funcs {
    ( $( $pin_ty:ident => $enum:ident { $( $var:ident = $val:literal ),* $(,)? } ),* $(,)? ) => {
        $(
            #[derive(Clone, Copy, PartialEq, Eq, Debug)]
            #[repr(u8)]
            pub enum $enum {
                $( $var = $val ),*
            }
            impl crate::gpio::PinFunc for $enum {
                #[inline]
                fn value(self) -> u8 { self as u8 }
            }
            impl crate::gpio::PinFuncOf<crate::gpio::$pin_ty> for $enum {}
        )*
    };
}

pub mod b {
    pad_funcs! {
        PB0 => Pin0Func { SdD6 = 6 },
        PB1 => Pin1Func { SdD7 = 5 },
    }
}

pub mod m {
    pad_funcs! {
        PM2 => Pin2Func { SdClk = 7 },
        PM3 => Pin3Func { SdDet = 7 },
        PM4 => Pin4Func { SdCmd = 8 },
        PM5 => Pin5Func { SdD0 = 8 },
        PM6 => Pin6Func { SdD1 = 6 },
    }
}

pub mod n {
    pad_funcs! {
        PN0 => Pin0Func { SdD2 = 7 },
        PN1 => Pin1Func { SdD3 = 6 },
        PN4 => Pin4Func { SdD4 = 9 },
        PN5 => Pin5Func { SdD5 = 11 },
    }
}
